// Rebuilds the generated parts of this design system after you edit it:
//   tokens.css           from tokens.json
//   components/bundle.css  the block between @generated:start and @generated:end:
//                          logos and the app icon from assets/Logos and assets/Marks,
//                          icon masks from assets/Icons
// Run from the repository root: node scripts/build.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = process.argv[2] || path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const t = JSON.parse(fs.readFileSync(path.join(root, 'tokens.json'), 'utf8'));
const themes = t.color.themes.map((x) => x.id);
const first = themes[0];
const ref = (v) => (v.startsWith('{') ? `var(--${v.slice(1, -1)})` : v);
const val = (tok, th) => (typeof tok.value === 'string' ? (th === first ? tok.value : null) : tok.value[th] ?? null);

let out = `/* ${t.name} — generated from tokens.json */\n\n`;

for (const f of t.type.fonts) {
  out += `@font-face { font-family: "${f.family}"; src: url("${f.file}") format("truetype"); font-weight: ${f.weight}; font-style: ${f.style || 'normal'}; font-display: swap; }\n`;
}

out += `\n:root, [data-theme="${first}"] {\n`;
for (const tok of t.color.tokens) out += `  --${tok.name}: ${ref(val(tok, first))};\n`;
for (const tok of t.shadow.tokens) out += `  --${tok.name}: ${tok.value};\n`;
out += `}\n`;

for (const th of themes.slice(1)) {
  out += `\n[data-theme="${th}"] {\n  color-scheme: dark;\n`;
  for (const tok of t.color.tokens) {
    const v = val(tok, th);
    if (v != null) out += `  --${tok.name}: ${ref(v)};\n`;
  }
  out += `}\n`;
}

out += `\n:root {\n`;
for (const fam of ['spacing', 'radius', 'layout']) for (const tok of t[fam].tokens) out += `  --${tok.name}: ${tok.value};\n`;
for (const [k, v] of Object.entries(t.type.families)) out += `  --font-${k}: ${v};\n`;
out += `}\n\n`;

for (const g of t.type.groups) {
  for (const s of g.styles) {
    const fam = s.family || g.family;
    const lines = [`font-family: var(--font-${fam});`, `font-size: ${s.fontSize};`, `line-height: ${s.lineHeight};`, `font-weight: ${s.fontWeight};`];
    if (s.letterSpacing) lines.push(`letter-spacing: ${s.letterSpacing};`);
    if (s.fontStyle) lines.push(`font-style: ${s.fontStyle};`);
    out += `.${s.name} { ${lines.join(' ')} }\n`;
  }
}

fs.writeFileSync(path.join(root, 'tokens.css'), out);

// Logo data URIs
const files = [
  ['logo-ink', 'assets/Logos/haysam-logo-ink.svg'],
  ['logo-yellow-ink', 'assets/Logos/haysam-logo-yellow-ink.svg'],
  ['logo-yellow-white', 'assets/Logos/haysam-logo-yellow-white.svg'],
  ['logo-white', 'assets/Logos/haysam-logo-white.svg'],
  ['logo-black', 'assets/Logos/haysam-logo-black.svg'],
  ['mark-ink', 'assets/Marks/haysam-mark-ink.svg'],
  ['mark-yellow', 'assets/Marks/haysam-mark-yellow.svg'],
  ['mark-white', 'assets/Marks/haysam-mark-white.svg'],
  ['mark-black', 'assets/Marks/haysam-mark-black.svg'],
  ['app-icon', 'assets/Marks/haysam-app-icon.svg'],
];
let css = `/* @generated:start */\n/* Generated by scripts/build.mjs from assets/Logos, assets/Marks and assets/Icons. Do not edit by hand. */\n:root {\n`;
for (const [k, p] of files) {
  const b64 = fs.readFileSync(path.join(root, p)).toString('base64');
  css += `  --hs-${k}: url("data:image/svg+xml;base64,${b64}");\n`;
}
const icons = fs.readdirSync(path.join(root, 'assets/Icons')).filter((f) => f.endsWith('.svg')).sort();
for (const f of icons) {
  const b64 = fs.readFileSync(path.join(root, 'assets/Icons', f)).toString('base64');
  css += `  --hs-i-${f.slice(0, -4)}: url("data:image/svg+xml;base64,${b64}");\n`;
}
css += `}\n`;
for (const f of icons) css += `.hs-i--${f.slice(0, -4)} { --hs-i: var(--hs-i-${f.slice(0, -4)}); }\n`;
css += `/* @generated:end */`;
const bundlePath = path.join(root, 'components/bundle.css');
const bundle = fs.readFileSync(bundlePath, 'utf8');
const re = /\/\* @generated:start \*\/[\s\S]*?\/\* @generated:end \*\//;
if (!re.test(bundle)) throw new Error('components/bundle.css is missing the @generated:start / @generated:end markers');
fs.writeFileSync(bundlePath, bundle.replace(re, () => css));
console.log('Wrote tokens.css and the generated block in components/bundle.css');
